'use strict';
let friendSetup=null,friendSetupLoaded=false,friendSetupPromise=null,friendDeckDraft=null,friendDeckSelected=0,friendDeckSaving=false,friendDeckLimit=120,friendFormationPointer=null,friendFormationOffset={x:0,y:0};
async function loadFriendSetup(){if(friendSetupLoaded)return;if(friendSetupPromise)return friendSetupPromise;friendSetupPromise=(async()=>{const result=await playerApi('/api/friends/setup');friendSetup=result.setup;friendSetupLoaded=true;renderFriendDeckSummary();})().finally(()=>friendSetupPromise=null);return friendSetupPromise;}
function resolvedFriendSetup(){
 const source=friendSetup?.items||gameState.deck.map(instanceId=>({instanceId})),chosen=[],used=new Set();
 for(let n=0;n<3;n++){const saved=source[n],item=gameState.inventory.find(i=>i.instanceId===saved?.instanceId&&!used.has(i.instanceId))||gameState.deck.map(id=>gameState.inventory.find(i=>i.instanceId===id&&!used.has(id))).find(Boolean)||gameState.inventory.find(i=>!used.has(i.instanceId));if(!item)continue;used.add(item.instanceId);const allowed=getUnlockedReadings(item),selected=saved?.instanceId===item.instanceId?saved.equippedReadings?.filter(r=>allowed.includes(r)):null;chosen.push({instanceId:item.instanceId,char:item.char,level:item.level||1,equippedReadings:selected?.length?selected.slice():getEquippedReadings(item)});}
 return {items:chosen,formation:KanjiFormation.copy(friendSetup?.formation||getActiveFormation())};
}
function friendItem(slot){const item=gameState.inventory.find(i=>i.instanceId===slot?.instanceId);return item?{...item,equippedReadings:slot.equippedReadings.slice(),ruby:slot.equippedReadings[0]}:null;}
function friendEditorRule(){return typeof onlineEditor!=='undefined'&&onlineEditor?onlineRuleSelected:friendEffectiveRule();}
function friendBattleItem(item){return item&&friendEditorRule()==='balanced'?{...item,level:KanjiOnlineRules.level}:item;}
window.recommendFriendDeck=()=>{if(friendDeckSaving||!friendDeckDraft)return;const rule=friendEditorRule(),choices=KanjiMatchRecommendation.recommend(gameState.inventory,(_,item)=>getUnlockedReadings(item),getKanjiStats,rule);if(choices.length!==3){document.getElementById('friend-deck-status').textContent=rule==='balanced'?'コスト16以内で3体組める文字が不足しています。召喚で文字を増やすか、自由ルールを選んでください。':'文字を3体用意してください。';return;}friendDeckDraft.items=choices.map(c=>({instanceId:c.instanceId,char:c.char,level:c.level,equippedReadings:c.equippedReadings.slice()}));fitFriendFormation();renderFriendDeck();document.getElementById('friend-deck-status').textContent=choices.map(c=>c.role+'：'+c.char).join(' ／ ')+'。この編成を保存すると次の対戦に使えます。';};
function renderFriendDeckSummary(){const setup=resolvedFriendSetup();document.getElementById('friend-deck-summary').textContent='対戦用：'+setup.items.map(i=>i.char).join('・')+'（通常デッキとは別に保存） / '+KanjiTeamLinks.describe(setup.items);}
window.openFriendDeckEditor=async()=>{
 if(friendBusy||friendDeckSaving)return;if(friendRoom?.status==='playing'){setFriendStatus('対局終了後に編成を変更できます。');return;}if(friendRoom?.ready?.[friendRoom.side]&&friendRoom.mode!=='online'){setFriendStatus('準備を取り消してから編成を変更してください。');return;}if(friendRoom?.ready?.[friendRoom.side]){await cancelFriendReady();if(friendRoom?.status==='playing'||friendRoom?.ready?.[friendRoom.side])return;}
 pausePlayerOverlay();try{await loadFriendSetup();}catch(error){setFriendStatus(error.message+' 保存済みの編成を読み込めないため、再接続後にお試しください。');return;}
 friendDeckDraft=resolvedFriendSetup();friendDeckSelected=0;friendDeckLimit=60;friendFormationPointer=null;resetFriendPicker(false);renderFriendDraftFavorites();document.getElementById('friend-deck-search').value='';document.getElementById('friend-deck-status').textContent='';document.getElementById('modal-friends').classList.add('hidden');document.getElementById('modal-friend-deck').classList.remove('hidden');document.querySelector('#modal-friend-deck .ui-deck-scroll').scrollTop=0;fitFriendFormation();renderFriendDeck();resizeFriendFormation();
};
window.closeFriendDeckEditor=()=>{if(friendDeckSaving)return;friendFormationPointer=null;document.getElementById('modal-friend-deck').classList.add('hidden');friendDeckDraft=null;if(friendRoom?.status==='preparing'){onlineEditor=false;switchTab('battle');renderBattlePreparation();return;}openFriendLobby();document.getElementById('btn-friend-deck').focus();};
function fitFriendFormation(){if(!friendDeckDraft)return;const items=friendDeckDraft.items.map(friendItem).filter(Boolean);friendDeckDraft.formation=KanjiFormation.fit(items,friendDeckDraft.formation).points;}
function renderFriendDeck(){if(!friendDeckDraft)return;const rule=friendEditorRule(),balanced=rule==='balanced',cost=KanjiOnlineRules.total(friendDeckDraft.items.map(friendItem));document.getElementById('friend-deck-rule').textContent=KanjiOnlineRules.label(rule)+'：'+KanjiOnlineRules.description(rule)+(balanced?` ／ コスト ${cost} / 16。${KanjiOnlineRules.costGuide}`:'');document.getElementById('btn-friend-recommend').disabled=friendDeckSaving;const box=document.getElementById('friend-deck-slots');box.replaceChildren();friendDeckDraft.items.forEach((slot,n)=>{const b=document.createElement('button');b.className='friend-deck-slot practice-team-slot';b.setAttribute('aria-pressed',String(friendDeckSelected===n));b.dataset.friendSlot=n;const char=document.createElement('strong');char.className='kanji-font';char.textContent=slot.char;const label=document.createElement('small');const item=friendItem(slot);label.textContent=`枠${n+1}・Lv.${balanced?10:slot.level}・${getCharacterTypeLabel(item)}・${ATTR_INFO[item.attr].name}`;b.append(char,label);b.onclick=()=>{friendDeckSelected=n;renderFriendDeck();};box.append(b);});
 const slot=friendDeckDraft.items[friendDeckSelected],item=friendItem(slot),rubies=document.getElementById('friend-deck-rubies');rubies.replaceChildren();if(item){const title=document.createElement('h3');title.textContent=isSecretKanji(item)?`${item.char}：シークレット・錬成限定（ルビなし）`:`${item.char}の装備ルビ`;rubies.append(title);for(const ruby of getUnlockedReadings(item)){const label=document.createElement('label'),input=document.createElement('input');input.type='checkbox';input.checked=slot.equippedReadings.includes(ruby);input.dataset.friendRuby=ruby;input.onchange=()=>{if(!input.checked&&slot.equippedReadings.length===1){input.checked=true;document.getElementById('friend-deck-status').textContent='ルビは1個以上装備してください。';return;}slot.equippedReadings=input.checked?[...slot.equippedReadings,ruby]:slot.equippedReadings.filter(r=>r!==ruby);renderFriendDeck();};const ability=getReadingAbilities({...item,equippedReadings:[ruby],ruby})[0];label.append(input,document.createTextNode(ruby+(ability?'・'+ability.name:'')));rubies.append(label);}const stats=getKanjiStats(friendBattleItem({...item,teamLink:KanjiTeamLinks.active(friendDeckDraft.items)?.id}));document.getElementById('friend-deck-stats').textContent=`威力 ${stats.power}・重量 ${stats.weight} ／ ${getReadingAbilities(item).map(a=>a.name).join('＋')} ／ ${KanjiTeamLinks.describe(friendDeckDraft.items)}`;}
 const presets=document.getElementById('friend-formation-presets');presets.replaceChildren();const preset=(text,points)=>{const b=document.createElement('button');b.className='inventory-action secondary';b.textContent=text;b.disabled=!points;b.onclick=()=>{friendDeckDraft.formation=KanjiFormation.copy(points);fitFriendFormation();drawFriendFormation();document.getElementById('friend-deck-status').textContent=text+'を読み込みました。';};presets.append(b);};preset('標準',KanjiFormation.defaults);gameState.formationPresets.forEach((p,n)=>preset('配置'+(n+1),p));renderFriendDeckChoices();drawFriendFormation();
}
window.renderFriendDeckChoices=reset=>{if(!friendDeckDraft)return;if(reset)friendDeckLimit=60;const items=KanjiPracticePicker.filter(gameState.inventory,{query:document.getElementById('friend-deck-search').value,...Object.fromEntries(['jis','attr','ability','sort'].map(k=>[k,document.getElementById('friend-filter-'+k).value]))},getRealReadings,i=>getReadingAbilities(i),getKanjiStats,i=>getUnlockedReadings(i).length,KanjiTurnOrder.count),box=document.getElementById('friend-deck-choices');box.replaceChildren();for(const item of items.slice(0,friendDeckLimit)){const b=document.createElement('button');b.type='button';b.className='friend-deck-choice practice-owned-choice';b.dataset.friendItem=item.instanceId;const index=friendDeckDraft.items.findIndex(i=>i.instanceId===item.instanceId);b.setAttribute('aria-pressed',String(index!==-1));b.setAttribute('aria-label',`${item.char} Lv.${item.level||1}を枠${friendDeckSelected+1}に編成`);const char=document.createElement('strong');char.className='kanji-font';char.textContent=item.char;const label=document.createElement('small');label.textContent=`所持Lv.${item.level||1}・ルビ${getUnlockedReadings(item).length}個・${getCharacterTypeLabel(item)}・${ATTR_INFO[item.attr].name}${index!==-1?'・枠'+(index+1):''}`;b.append(char,label);b.onclick=()=>{const current=friendDeckDraft.items[friendDeckSelected];if(index!==-1){friendDeckDraft.items[index]=current;}friendDeckDraft.items[friendDeckSelected]={instanceId:item.instanceId,char:item.char,level:item.level||1,equippedReadings:getEquippedReadings(item)};fitFriendFormation();renderFriendDeck();};box.append(b);}document.getElementById('friend-deck-count').textContent=`所持${items.length}体・${Math.min(items.length,friendDeckLimit)}体を表示`;if(!items.length)box.textContent='該当する文字がありません。';document.getElementById('btn-friend-deck-more').hidden=items.length<=friendDeckLimit;};
window.showMoreFriendDeckChoices=()=>{friendDeckLimit+=60;renderFriendDeckChoices();};
function friendFormationMetrics(){const c=document.getElementById('friend-formation-canvas');return {c,r:Math.min(c.width*.45,c.height-22),center:{x:c.width/2,y:10}};}
function friendFormationBodies(){const {r,center}=friendFormationMetrics();return friendDeckDraft.items.map((slot,n)=>{const item=friendItem(slot),p=friendDeckDraft.formation[n],b=KanjiTraits.createBody(item,center.x+p.x*r,center.y+p.y*r,r/150,{},p.angle);b.gameData={...item,isPlayer:true};return b;});}
function drawFriendFormation(){if(!friendDeckDraft)return;const {c,r,center}=friendFormationMetrics(),cx=c.getContext('2d');cx.clearRect(0,0,c.width,c.height);cx.fillStyle='#020617';cx.beginPath();cx.arc(center.x,center.y,r,0,Math.PI);cx.closePath();cx.fill();cx.strokeStyle='#d97706';cx.lineWidth=2;cx.stroke();friendFormationBodies().forEach((b,n)=>{KanjiPieceArt.draw(cx,b,performance.now(),true);if(n===friendDeckSelected){cx.strokeStyle='#67e8f9';cx.setLineDash([4,4]);cx.beginPath();cx.arc(b.position.x,b.position.y,b.circleRadius+9,0,Math.PI*2);cx.stroke();cx.setLineDash([]);}});}
function resizeFriendFormation(){if(!friendDeckDraft||document.getElementById('modal-friend-deck').classList.contains('hidden'))return;const c=document.getElementById('friend-formation-canvas');c.width=Math.round(c.clientWidth);c.height=Math.round(c.clientHeight);drawFriendFormation();}
window.rotateFriendFormation=angle=>{if(!friendDeckDraft)return;const n=friendDeckSelected,p=friendDeckDraft.formation[n],items=friendDeckDraft.items.map(friendItem),next=KanjiFormation.move(items,friendDeckDraft.formation,n,{...p,angle:KanjiFormation.wrapAngle(p.angle+angle)});if(next){friendDeckDraft.formation=next;drawFriendFormation();}else document.getElementById('friend-deck-status').textContent='他のコマや境界に触れるため回転できません。少し動かしてください。';};
window.saveFriendDeck=async()=>{if(friendDeckSaving||!friendDeckDraft)return;const setup=JSON.parse(JSON.stringify(friendDeckDraft)),status=document.getElementById('friend-deck-status');if(friendEditorRule()==='balanced'&&KanjiOnlineRules.total(setup.items.map(friendItem))>16){status.textContent='統一ルールはコスト16以内にしてください。「おすすめ編成」でも調整できます。';return;}if(setup.items.length!==3||!KanjiFormation.valid(setup.items.map(friendItem),setup.formation)){status.textContent='3体の文字と初期配置を確認してください。';return;}friendDeckSaving=true;document.getElementById('btn-friend-deck-save').disabled=true;status.textContent='保存中…';try{const result=await playerApi('/api/friends/setup','PUT',setup);friendSetup=result.setup;friendSetupLoaded=true;renderFriendDeckSummary();if(friendRoom&&!friendRoom.departed&&(friendRoom.status==='preparing'||friendRoom.mode==='friend'&&['waiting','finished'].includes(friendRoom.status))){try{acceptFriendRoom(await playerApi(`/api/friends/rooms/${friendRoom.code}/roster`,'POST',{round:friendRoom.round,revision:friendRoom.revision,lineupRevision:friendRoom.lineupRevision,team:friendRoster()}),false);}catch(error){if(error.status!==409)throw error;if(friendRoom?.status==='preparing'){acceptFriendRoom(await playerApi(`/api/friends/rooms/${friendRoom.code}`),false);throw error;}setFriendStatus('対局が始まりました。保存した編成は次のバトルから反映されます。');}}status.textContent=friendRoom?.status==='preparing'?'保存しました。対局前の編成に反映しました。':'保存しました。次のバトルに反映します。';}catch(error){status.textContent=error.message+' 編成はこの画面に残っています。';}finally{friendDeckSaving=false;document.getElementById('btn-friend-deck-save').disabled=false;}};
window.addEventListener('load',()=>{const c=document.getElementById('friend-formation-canvas');const point=e=>{const r=c.getBoundingClientRect();return{x:(e.clientX-r.left)*c.width/r.width,y:(e.clientY-r.top)*c.height/r.height};};c.addEventListener('pointerdown',e=>{if(!friendDeckDraft||e.isPrimary===false||e.button!==0||friendFormationPointer!==null)return;const p=point(e),bodies=friendFormationBodies(),hit=bodies.map((b,n)=>({b,n})).filter(({b})=>KanjiTraits.hitTest(b,p,18)).sort((a,b)=>Math.hypot(a.b.position.x-p.x,a.b.position.y-p.y)-Math.hypot(b.b.position.x-p.x,b.b.position.y-p.y))[0];if(!hit)return;e.preventDefault();friendDeckSelected=hit.n;friendFormationPointer=e.pointerId;friendFormationOffset={x:p.x-hit.b.position.x,y:p.y-hit.b.position.y};c.setPointerCapture(e.pointerId);renderFriendDeck();});c.addEventListener('pointermove',e=>{if(!friendDeckDraft||e.pointerId!==friendFormationPointer)return;e.preventDefault();const p=point(e),{r,center}=friendFormationMetrics(),n=friendDeckSelected,next=KanjiFormation.move(friendDeckDraft.items.map(friendItem),friendDeckDraft.formation,n,{x:(p.x-friendFormationOffset.x-center.x)/r,y:(p.y-friendFormationOffset.y-center.y)/r,angle:friendDeckDraft.formation[n].angle});if(next){friendDeckDraft.formation=next;drawFriendFormation();}});const cancel=()=>{const id=friendFormationPointer;friendFormationPointer=null;if(id!==null&&c.hasPointerCapture(id))c.releasePointerCapture(id);};c.addEventListener('pointerup',cancel);c.addEventListener('pointercancel',cancel);c.addEventListener('lostpointercapture',()=>friendFormationPointer=null);window.addEventListener('resize',()=>{cancel();requestAnimationFrame(resizeFriendFormation);});new ResizeObserver(resizeFriendFormation).observe(c);});

window.resetFriendPicker=(render=true)=>{document.getElementById('friend-deck-search').value='';for(const k of ['jis','attr','ability'])document.getElementById('friend-filter-'+k).value='';document.getElementById('friend-filter-sort').value='owned';const a=document.getElementById('friend-filter-ability');if(a.options.length===1)for(const ability of Object.values(KanjiReadAbilities.abilities)){const o=document.createElement('option');o.value=ability.id;o.textContent=ability.name;a.append(o);}if(render)renderFriendDeckChoices(true);};
function renderFriendDraftFavorites(){const select=document.getElementById('friend-draft-favorite');select.replaceChildren();for(const f of gameState.deckFavorites||[]){const o=document.createElement('option');o.value=String(f.slot);o.textContent=f.name+'：'+f.items.map(i=>i.char).join('・');select.append(o);}}
window.useFriendDeploymentDeck=()=>{if(!friendDeckDraft||friendDeckSaving)return;friendDeckDraft={items:gameState.deck.map(id=>gameState.inventory.find(i=>i.instanceId===id)).filter(Boolean).map(i=>({instanceId:i.instanceId,char:i.char,level:i.level,equippedReadings:getEquippedReadings(i).slice()})),formation:KanjiFormation.copy(getActiveFormation())};fitFriendFormation();renderFriendDeck();};
window.useFriendDraftFavorite=()=>{if(!friendDeckDraft||friendDeckSaving)return;const f=(gameState.deckFavorites||[]).find(f=>String(f.slot)===document.getElementById('friend-draft-favorite').value),status=document.getElementById('friend-deck-status');if(!f){status.textContent='文字の編成からお気に入りを登録してください。';return;}const r=KanjiDeckFavorites.resolve(f,gameState.inventory,getUnlockedReadings);if(r.missing.length){status.textContent='所持していない文字：'+r.missing.join('・');return;}friendDeckDraft={items:r.items.map(({item,equippedReadings})=>({instanceId:item.instanceId,char:item.char,level:item.level,equippedReadings:equippedReadings.slice()})),formation:KanjiFormation.copy(f.formation||KanjiFormation.defaults)};fitFriendFormation();renderFriendDeck();status.textContent='「'+f.name+'」を呼び出しました。編成を確定すると反映します。';};
